        accumulate<T>(bk, nbf, c, chi + (int64_t)0*nbf*npts + g0, npts, W, 1);
        stage_a<T, Txc>(g0, bk, 8, detail_xck_mgga_r_fg::c0_1, detail_xck_mgga_r_fg::o0_1, detail_xck_mgga_r_fg::f0_1, detail_xck_mgga_r_fg::NFLD, fi, xc, c);
