        accumulate<T>(bk, nbf, c, X0, bk, W, 0);
        stage_a<T, Txc>(g0, bk, 1, detail_xck_mgga_r_fg::c0_5, detail_xck_mgga_r_fg::o0_5, detail_xck_mgga_r_fg::f0_5, detail_xck_mgga_r_fg::NFLD, fi, xc, c);
